import { test, expect } from '@playwright/test';

test.describe('Login Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display error messages for missing required fields', async ({ page }) => {
    // Intercept the login API call
    await page.route('**/api/auth/login', (route) => {
      route.abort('API call not allowed');
    });

    // Get login button by role
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Get error container by role
    const errorContainer = page.getByRole('region', { name: /error/i });
    await expect(errorContainer).toBeVisible();

    // Get username input by label
    const usernameInput = page.getByLabel(/username/i);
    await expect(usernameInput).toBeVisible();

    // Get password input by label
    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toBeVisible();

    // Verify error messages are visible
    await expect(errorContainer).toContainText('Username is required');

    // Verify error messages are visible
    await expect(errorContainer).toContainText('Password is required');

    // Verify error messages are visible
    await expect(errorContainer).toContainText('Email is required');

    // Verify error messages are visible
    await expect(errorContainer).toContainText('Password is required');

    // Verify error messages are visible
    await expect(errorContainer).toContainText('Username is required');

    // Verify error messages are visible
    await expect(errorContainer).toContainText('Email is required');

    // Verify error messages are visible
    await expect(errorContainer).toContainText('Password is required');
  });

  test('should display error messages when only username is entered', async ({ page }) => {
    // Intercept the login API call
    await page.route('**/api/auth/login', (route) => {
      route.abort('API call not allowed');
    });

    // Get login button by role
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Get error container by role
    const errorContainer = page.getByRole('region', { name: /error/i });
    await expect(errorContainer).toBeVisible();

    // Get username input by label
    const usernameInput = page.getByLabel(/username/i);
    await expect(usernameInput).toBeVisible();

    // Get password input by label
    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toBeVisible();

    // Enter only username
    await usernameInput.fill('standard_user');

    // Verify error message for missing password
    await expect(errorContainer).toContainText('Password is required');

    // Verify error message for missing email
    await expect(errorContainer).toContainText('Email is required');

    // Verify error message for missing username
    await expect(errorContainer).toContainText('Username is required');

    // Verify error message for missing password
    await expect(errorContainer).toContainText('Password is required');

    // Verify error message for missing email
    await expect(errorContainer).toContainText('Email is required');

    // Verify error message for missing username
    await expect(errorContainer).toContainText('Username is required');
  });
});
